mapper.select:
SELECT id, type, name, status, phase, parent_id, path,
      updated_at, cpu, memory, restarts
  FROM resource
WHERE parent_id = #{parentId}

  AND status = #{status}

ORDER BY id

mapper.update:
UPDATE resource
   SET cpu = #{cpu},
       memory = #{memory},
       updated_at = #{now}
 WHERE id = #{id}
